#!/usr/bin/env python3
import base64
import hashlib
import requests
import urllib.parse

# Server URL
BASE_URL = "http://crypto.chal.csaw.io:5000"

def b64encode(data):
    """Base64 encode data"""
    if isinstance(data, str):
        data = data.encode()
    return base64.b64encode(data).decode()

def b64decode(data):
    """Base64 decode data"""
    if isinstance(data, str):
        data = data.encode()
    return base64.b64decode(data).decode()

def urlencode(data):
    """URL encode data"""
    return urllib.parse.quote(data)

def urldecode(data):
    """URL decode data"""
    return urllib.parse.unquote(data)

def calculate_hmac(identifier):
    """Calculate HMAC using SHA1"""
    # Convert base64 id back to original encoding for HMAC calculation
    raw_data = base64.b64decode(identifier).decode('unicode-escape').encode('ISO-8859-1')
    hasher = hashlib.sha1()
    hasher.update(b":p" + raw_data)  # Using SECRET from handout.py
    return hasher.hexdigest()

def create_note(author, note):
    """Create a new note"""
    data = {
        'author': author,
        'note': note
    }
    response = requests.post(f"{BASE_URL}/new", data=data)
    return response.text.strip()

def view_note(note_id, integrity):
    """View a note"""
    data = {
        'id': note_id,
        'integrity': integrity
    }
    response = requests.post(f"{BASE_URL}/view", data=data)
    return response.text.strip()

def test_functionality():
    """Test basic functionality"""
    print("[+] Testing note creation...")
    # Create a test note
    test_author = "test_user"
    test_note = "This is a test note"

    create_response = create_note(test_author, test_note)
    print(f"[+] Create note response: {create_response}")

    # Parse the response (format: identifier:integrity)
    if ":" in create_response:
        note_id, integrity = create_response.split(":")

        print("[+] Testing note viewing...")
        view_response = view_note(note_id, integrity)
        print(f"[+] View note response: {view_response}")
    else:
        print("[-] Failed to create note!")

if __name__ == "__main__":
    test_functionality()

